  '. A customer sets a password with a code sent to their WhatsApp, or from their re-order page.': [
    '। ग्राहक अपने WhatsApp पर भेजे गए कोड से, या अपने री-ऑर्डर पेज से पासवर्ड सेट करता है।',
    '. ग्राहक त्याच्या WhatsApp वर पाठवलेल्या कोडने, किंवा त्याच्या री-ऑर्डर पेजवरून पासवर्ड सेट करतो.',
  ],
  '. All message origination headers, telecom identifiers, and virtual DIDs are linked to verifiable legal entities.':
    [
      '। सभी संदेश हेडर, टेलीकॉम पहचानकर्ता और वर्चुअल DID सत्यापित कानूनी संस्थाओं से जुड़े हैं।',
      '. सर्व संदेश हेडर, टेलिकॉम ओळखकर्ते आणि व्हर्च्युअल DID पडताळणीयोग्य कायदेशीर संस्थांशी जोडलेले आहेत.',
    ],
  ". Enquiries arrive as quotation drafts from “Public catalogue”; the number isn't verified, so call before quoting.":
    [
      '। पूछताछ “Public catalogue” से कोटेशन ड्राफ़्ट के रूप में आती है; नंबर सत्यापित नहीं है, इसलिए कोटेशन से पहले कॉल करें।',
      '. चौकशी “Public catalogue” मधून कोटेशन ड्राफ्ट म्हणून येते; नंबर पडताळलेला नाही, म्हणून कोटेशनपूर्वी कॉल करा.',
    ],
  '. It does not contain your menu — only the plumbing. After that, everything you edit below is live.':
    [
      '। इसमें आपका मेन्यू नहीं है — सिर्फ़ ढाँचा। उसके बाद, नीचे आप जो भी बदलेंगे वह तुरंत लागू होगा।',
      '. यात तुमचा मेनू नाही — फक्त रचना. त्यानंतर खाली तुम्ही जे बदलाल ते लगेच लागू होईल.',
    ],
  '. Open it, then come back and press “I’ve opened the link”.': [
    '। इसे खोलें, फिर वापस आकर “मैंने लिंक खोल लिया” दबाएँ।',
    '. ते उघडा, मग परत येऊन “मी लिंक उघडली” दाबा.',
  ],
  '. Parts are matched to the catalogue by part number.': [
    '। पार्ट नंबर से पार्ट्स को कैटलॉग से मिलाया जाता है।',
    '. पार्ट नंबरवरून पार्ट्स कॅटलॉगशी जुळवले जातात.',
  ],
  ". Pick something you don't use anywhere else.": [
    '। ऐसा कुछ चुनें जो आप कहीं और इस्तेमाल न करते हों।',
    '. असे काहीतरी निवडा जे तुम्ही इतरत्र वापरत नाही.',
  ],
  '. Planned: {0} units.': ['। योजना: {0} यूनिट।', '. नियोजित: {0} युनिट.'],
  '. Run “Create or update tables” after pointing it at a new database, and after each release.': [
    '। नए डेटाबेस पर लगाने के बाद, और हर रिलीज़ के बाद “टेबल बनाएँ या अपडेट करें” चलाएँ।',
    '. नवीन डेटाबेसकडे निर्देशित केल्यानंतर, आणि प्रत्येक रिलीजनंतर “टेबल तयार किंवा अपडेट करा” चालवा.',
  ],
  '. The customer is still on the line.': [
    '। ग्राहक अब भी लाइन पर है।',
    '. ग्राहक अजूनही लाइनवर आहे.',
  ],
  '. The number arrives on the Cloud API with no past conversations, and the app can no longer be used with this number afterwards. Broadcast lists and labels do not migrate either.':
    [
      '। नंबर बिना पिछली बातचीत के Cloud API पर आता है, और उसके बाद इस नंबर के साथ ऐप इस्तेमाल नहीं हो सकता। ब्रॉडकास्ट सूचियाँ और लेबल भी नहीं आते।',
      '. नंबर आधीच्या संभाषणांशिवाय Cloud API वर येतो, आणि त्यानंतर या नंबरसोबत अॅप वापरता येत नाही. ब्रॉडकास्ट याद्या आणि लेबलही येत नाहीत.',
    ],
  '. The platform team then confirms it.': [
    '। फिर प्लेटफ़ॉर्म टीम इसकी पुष्टि करती है।',
    '. मग प्लॅटफॉर्म टीम याची खात्री करते.',
  ],
  '. The signature is an HMAC-SHA256 over': [
    '। सिग्नेचर एक HMAC-SHA256 है, इस पर',
    '. सिग्नेचर हा HMAC-SHA256 आहे, यावर',
  ],
  ". To ask a tenant to action one of these on MNI Assist's infrastructure, contact us directly (below) and we will route it to the responsible tenant and confirm once it is done.":
    [
      '। MNI Assist के इंफ्रास्ट्रक्चर पर किसी वर्कस्पेस से इनमें से कोई काम करवाने के लिए हमसे सीधे संपर्क करें (नीचे), हम इसे ज़िम्मेदार वर्कस्पेस तक पहुँचाएँगे और पूरा होने पर पुष्टि करेंगे।',
      '. MNI Assist च्या इन्फ्रास्ट्रक्चरवर एखाद्या वर्कस्पेसकडून यापैकी काही करून घेण्यासाठी आमच्याशी थेट संपर्क साधा (खाली), आम्ही ते जबाबदार वर्कस्पेसकडे पाठवू आणि पूर्ण झाल्यावर कळवू.',
    ],
