  'A vCard (.vcf)': ['vCard (.vcf)', 'vCard (.vcf)'],
  'A visiting card photo': ['विज़िटिंग कार्ड की फ़ोटो', 'व्हिजिटिंग कार्डचा फोटो'],
  'A website button, a printed QR code, or an exhibition link — each one tracked separately. Pausing a link keeps it working but stops it counting new clicks.':
    [
      'वेबसाइट बटन, छपा QR कोड, या प्रदर्शनी लिंक — हर एक अलग से ट्रैक होता है। लिंक रोकने पर वह काम करता रहता है पर नए क्लिक नहीं गिनता।',
      'वेबसाइट बटण, छापलेला QR कोड, किंवा प्रदर्शन लिंक — प्रत्येक वेगळा ट्रॅक होतो. लिंक थांबवल्यास ती चालू राहते पण नवीन क्लिक मोजत नाही.',
    ],
  'A working checklist, not legal advice. Most checks read what MNI Assist already records (consent evidence, opt-outs, retention, requests, breaches); the rest need the details below. The notice draft is a starting point for your lawyer.':
    [
      'काम की चेकलिस्ट, कानूनी सलाह नहीं। ज़्यादातर जाँच वह पढ़ती हैं जो MNI Assist पहले से दर्ज करता है (सहमति के प्रमाण, ऑप्ट-आउट, रिटेंशन, अनुरोध, उल्लंघन); बाकी के लिए नीचे का विवरण चाहिए। नोटिस ड्राफ़्ट आपके वकील के लिए शुरुआती बिंदु है।',
      'कामाची चेकलिस्ट, कायदेशीर सल्ला नाही. बहुतेक तपासण्या MNI Assist आधीच जे नोंदवते ते वाचतात (संमतीचे पुरावे, ऑप्ट-आउट, जतन, विनंत्या, उल्लंघने); बाकीसाठी खालील तपशील हवा. नोटीस ड्राफ्ट तुमच्या वकिलासाठी सुरुवात आहे.',
    ],
