      'इस नंबर में जो औद्योगिक टेम्पलेट अभी नहीं हैं उन्हें ड्राफ़्ट के रूप में जोड़ता है (जैसे quotation_ready, जिसमें कोटेशन PDF होता है)',
      'या नंबरकडे अजून नसलेले औद्योगिक टेम्पलेट ड्राफ्ट म्हणून जोडते (उदा. quotation_ready, ज्यात कोटेशन PDF असतो)',
