  'Automate follow-ups and capture structured enquiries.': [
    'फ़ॉलो-अप स्वचालित करें और व्यवस्थित पूछताछ दर्ज करें।',
    'फॉलो-अप स्वयंचलित करा आणि व्यवस्थित चौकशी नोंदवा.',
  ],
  "Automatic answers to customers who write in. The welcome goes to someone's first message. The away reply goes outside your business hours and on holidays, at most once per customer per wait period. During an out-of-office period that message is sent instead. Nothing is sent to a conversation an agent has taken, to button taps, or to STOP.":
    [
      'लिखने वाले ग्राहकों को अपने आप जवाब। स्वागत संदेश किसी के पहले संदेश पर जाता है। दूर-जवाब आपके कारोबारी समय के बाहर और छुट्टियों पर जाता है, हर ग्राहक को हर प्रतीक्षा अवधि में अधिकतम एक बार। ऑफ़िस से बाहर की अवधि में उसकी जगह वह संदेश जाता है। जिस बातचीत को एजेंट ने ले लिया हो, बटन टैप पर, या STOP पर कुछ नहीं भेजा जाता।',
      'लिहिणाऱ्या ग्राहकांना आपोआप उत्तरे. स्वागत संदेश एखाद्याच्या पहिल्या संदेशाला जातो. दूर-उत्तर तुमच्या व्यवसायाच्या वेळेबाहेर आणि सुट्ट्यांना जाते, प्रत्येक ग्राहकाला प्रत्येक प्रतीक्षा कालावधीत जास्तीत जास्त एकदा. ऑफिसबाहेरच्या कालावधीत त्याऐवजी तो संदेश जातो. एजंटने घेतलेल्या संभाषणाला, बटण टॅपला, किंवा STOP ला काहीही पाठवले जात नाही.',
    ],
