  'Build a form, put it on your website as a link or an embedded frame, and every submission makes or finds the contact, records what they agreed to, and opens an enquiry in your pipeline. It works alongside WhatsApp Flows and the chat widget.':
    [
      'एक फ़ॉर्म बनाएँ, उसे अपनी वेबसाइट पर लिंक या एम्बेडेड फ़्रेम के रूप में लगाएँ, और हर सबमिशन संपर्क बनाता या ढूँढता है, उनकी सहमति दर्ज करता है, और आपकी पाइपलाइन में पूछताछ खोलता है। यह WhatsApp Flows और चैट विजेट के साथ काम करता है।',
      'एक फॉर्म तयार करा, तो तुमच्या वेबसाइटवर लिंक किंवा एम्बेड केलेल्या फ्रेमच्या रूपात ठेवा, आणि प्रत्येक सबमिशन संपर्क तयार करते किंवा शोधते, त्यांनी कशाला संमती दिली ते नोंदवते, आणि तुमच्या पाइपलाइनमध्ये चौकशी उघडते. हे WhatsApp Flows आणि चॅट विजेटसोबत काम करते.',
    ],
  'Build an in-chat form screen by screen — add fields, mark which are required, and the WhatsApp Flow JSON is generated for you. No hand-written JSON needed.':
    [
      'चैट के भीतर फ़ॉर्म स्क्रीन-दर-स्क्रीन बनाएँ — फ़ील्ड जोड़ें, ज़रूरी चिह्नित करें, और WhatsApp Flow JSON आपके लिए बन जाता है। हाथ से JSON लिखने की ज़रूरत नहीं।',
      'चॅटमधील फॉर्म स्क्रीन-दर-स्क्रीन तयार करा — फील्ड जोडा, आवश्यक कोणते ते चिन्हांकित करा, आणि WhatsApp Flow JSON तुमच्यासाठी तयार होतो. हाताने JSON लिहायची गरज नाही.',
    ],
  'Build it from the products you already quote.': [
    'इसे उन प्रोडक्ट से बनाएँ जिनका आप पहले से कोटेशन देते हैं।',
    'तुम्ही आधीच कोटेशन देता त्या उत्पादनांमधून ते तयार करा.',
  ],
  "Build the automation as a list of steps, or on the canvas as boxes and arrows. On the canvas, drag a step to move it, drag from a dot on its bottom edge to another step to join them, and drag new steps in from the palette. 'If…' and 'Wait for a reply' have two ways out; a way out with nothing joined ends the journey there. Loops are not allowed.":
    [
      "ऑटोमेशन को चरणों की सूची के रूप में, या कैनवास पर बॉक्स और तीरों के रूप में बनाएँ। कैनवास पर, चरण को हिलाने के लिए खींचें, उसके निचले किनारे के बिंदु से दूसरे चरण तक खींचकर जोड़ें, और पैलेट से नए चरण खींचकर लाएँ। 'अगर…' और 'जवाब की प्रतीक्षा' के दो निकास हैं; जिस निकास से कुछ न जुड़ा हो वहाँ यात्रा ख़त्म होती है। लूप की अनुमति नहीं है।",
      "ऑटोमेशन पायऱ्यांची यादी म्हणून, किंवा कॅनव्हासवर बॉक्स आणि बाणांनी तयार करा. कॅनव्हासवर, पायरी हलवण्यासाठी ओढा, तिच्या खालच्या कडेवरील बिंदूपासून दुसऱ्या पायरीपर्यंत ओढून जोडा, आणि पॅलेटमधून नवीन पायऱ्या ओढून आणा. 'जर…' आणि 'उत्तराची वाट पहा' ला दोन बाहेर पडण्याचे मार्ग आहेत; ज्याला काही जोडलेले नाही तिथे प्रवास संपतो. लूपना परवानगी नाही.",
    ],
  'Build the menu here instead of in Exotel’s dashboard.': [
    'मेन्यू Exotel के डैशबोर्ड की जगह यहीं बनाएँ।',
    'मेनू Exotel च्या डॅशबोर्डऐवजी इथेच तयार करा.',
  ],
  'Build the steps in the builder.': ['बिल्डर में चरण बनाएँ।', 'बिल्डरमध्ये पायऱ्या तयार करा.'],
  'Building…': ['बन रहा है…', 'तयार होत आहे…'],
  'Built for': ['किसके लिए बना', 'कोणासाठी बनवले'],
  'Built in': ['अंतर्निहित', 'अंगभूत'],
