      'कॉलर तुमचा प्रॉम्प्ट ऐकतात आणि एक कळ दाबतात; मग कॉल फक्त त्या पर्यायाच्या टीमला वाजतो. प्रॉम्प्टमध्ये प्रत्येक पर्याय सांगा, उदा. “English साठी 1 दाबा; हिंदीसाठी 2 दाबा.”',
