  "Change what the platform's own emails say. The variables listed under each email, such as the workspace name, are filled in when it is sent. Keep the html.escape filter on anything a person typed, such as names. Restore default puts the original wording back.":
    [
      'प्लेटफ़ॉर्म के अपने ईमेल का संदेश बदलें। हर ईमेल के नीचे सूचीबद्ध वेरिएबल, जैसे वर्कस्पेस का नाम, भेजते समय भरे जाते हैं। किसी व्यक्ति की टाइप की गई चीज़ों, जैसे नाम, पर html.escape फ़िल्टर रखें। डिफ़ॉल्ट बहाल करें मूल शब्द वापस लाता है।',
      'प्लॅटफॉर्मच्या स्वतःच्या ईमेलमधील मजकूर बदला. प्रत्येक ईमेलखाली दिलेले व्हेरिएबल, जसे वर्कस्पेसचे नाव, पाठवताना भरले जातात. एखाद्याने टाइप केलेल्या गोष्टींवर, जसे नावे, html.escape फिल्टर ठेवा. डीफॉल्ट पुनर्संचयित करा मूळ शब्द परत आणते.',
    ],
