  'Company / plant': ['कंपनी / प्लांट', 'कंपनी / प्लांट'],
  'Company accounts': ['कंपनी खाते', 'कंपनी खाती'],
  "Company accounts go in as customers when they are created or edited, and a quotation marked won goes in once as a sales order — net of GST, which the ERP applies from its own tax setup. Invoices and each customer's outstanding balance are read back every six hours and shown on the account. Anything the ERP refuses is retried on the next pass.":
    [
      'कंपनी खाते बनाए या संपादित किए जाने पर ग्राहक के रूप में जाते हैं, और जीता हुआ चिह्नित कोटेशन एक बार सेल्स ऑर्डर के रूप में जाता है — GST के बिना, जिसे ERP अपने कर सेटअप से लगाता है। इनवॉइस और हर ग्राहक का बकाया हर छह घंटे वापस पढ़ा जाता है और खाते पर दिखता है। ERP जो भी अस्वीकार करे वह अगली बार फिर कोशिश होता है।',
      'कंपनी खाती तयार किंवा संपादित केल्यावर ग्राहक म्हणून जातात, आणि जिंकले म्हणून चिन्हांकित कोटेशन एकदा सेल्स ऑर्डर म्हणून जाते — GST वगळून, जो ERP स्वतःच्या कर सेटअपनुसार लावते. इनव्हॉइस आणि प्रत्येक ग्राहकाची थकबाकी दर सहा तासांनी परत वाचली जाते आणि खात्यावर दिसते. ERP जे नाकारते त्याचा पुढच्या वेळी पुन्हा प्रयत्न होतो.',
    ],
