      'शर्तें ऊपर से नीचे पढ़ी जाती हैं। नेस्टेड समूह का अपना जोड़ होता है, इसलिए “इनमें से कोई भी, और वे सभी” तीन नहीं बल्कि एक सेगमेंट है।',
