  'Each AMC renewal won': ['हर जीता AMC नवीनीकरण', 'प्रत्येक जिंकलेले AMC नूतनीकरण'],
  'Each Meta ad or boosted post that opened a chat or brought a lead-form lead, with the enquiries and wins that followed. Connect your ad account to see what each ad cost, and what each enquiry cost.':
    [
      'हर Meta विज्ञापन या बूस्टेड पोस्ट जिसने चैट खोली या लीड-फ़ॉर्म लीड लाई, उसके बाद की पूछताछ और जीत के साथ। हर विज्ञापन और हर पूछताछ की लागत देखने के लिए अपना विज्ञापन खाता जोड़ें।',
      'प्रत्येक Meta जाहिरात किंवा बूस्ट केलेली पोस्ट जिने चॅट उघडली किंवा लीड-फॉर्म लीड आणली, त्यानंतरच्या चौकशी आणि विजयांसह. प्रत्येक जाहिरात आणि प्रत्येक चौकशीचा खर्च पाहण्यासाठी तुमचे जाहिरात खाते जोडा.',
    ],
  'Each campaign from send to sale: replies, enquiries, value won and cost per enquiry.': [
    'भेजने से बिक्री तक हर अभियान: जवाब, पूछताछ, जीता मूल्य और प्रति पूछताछ लागत।',
    'पाठवणीपासून विक्रीपर्यंत प्रत्येक मोहीम: उत्तरे, चौकशी, जिंकलेले मूल्य आणि प्रति चौकशी खर्च.',
  ],
  'Each contact needs a WhatsApp-capable phone number. Numbers without a country code get the default one you choose next.':
    [
      'हर संपर्क का WhatsApp वाला फ़ोन नंबर होना चाहिए। बिना देश कोड वाले नंबरों को वह डिफ़ॉल्ट मिलता है जो आप आगे चुनेंगे।',
      'प्रत्येक संपर्काचा WhatsApp असलेला फोन नंबर हवा. देश कोड नसलेल्या नंबरना तुम्ही पुढे निवडाल तो डीफॉल्ट मिळतो.',
    ],
  'Each enquiry says which form and ad it came from, so you can see which ads bring real enquiries.':
    [
      'हर पूछताछ बताती है कि वह किस फ़ॉर्म और विज्ञापन से आई, ताकि आप देख सकें कौन से विज्ञापन असली पूछताछ लाते हैं।',
      'प्रत्येक चौकशी ती कोणत्या फॉर्म आणि जाहिरातीतून आली ते सांगते, म्हणजे कोणत्या जाहिराती खऱ्या चौकशी आणतात ते दिसते.',
    ],
  'Each goes to Meta for review. A submitted template can no longer be edited (only replaced by a new one), so check the drafts first.':
    [
      'हर एक समीक्षा के लिए Meta को जाता है। सबमिट किया टेम्पलेट फिर संपादित नहीं हो सकता (केवल नए से बदला जा सकता है), इसलिए पहले ड्राफ़्ट जाँचें।',
      'प्रत्येक पुनरावलोकनासाठी Meta कडे जाते. सबमिट केलेले टेम्पलेट नंतर संपादित करता येत नाही (फक्त नवीनने बदलता येते), म्हणून आधी ड्राफ्ट तपासा.',
    ],
  'Each holiday date can be listed once.': [
    'हर छुट्टी की तारीख़ एक बार ही दी जा सकती है।',
    'प्रत्येक सुट्टीची तारीख एकदाच देता येते.',
  ],
  'Each link and QR code is tracked separately, so you know what works.': [
    'हर लिंक और QR कोड अलग से ट्रैक होता है, ताकि आप जानें क्या काम करता है।',
    'प्रत्येक लिंक आणि QR कोड वेगळा ट्रॅक होतो, म्हणजे काय चालते ते कळते.',
  ],
  'Each link carries a short code in its pre-filled message. When the customer sends that first message the code comes back to us, so a website button, an email link and a stall QR code can be told apart — and counted.':
    [
      'हर लिंक के पहले से भरे संदेश में एक छोटा कोड होता है। ग्राहक जब वह पहला संदेश भेजता है तो कोड हमारे पास लौटता है, इसलिए वेबसाइट बटन, ईमेल लिंक और स्टॉल QR कोड अलग पहचाने — और गिने — जा सकते हैं।',
      'प्रत्येक लिंकच्या आधीच भरलेल्या संदेशात एक छोटा कोड असतो. ग्राहक तो पहिला संदेश पाठवतो तेव्हा कोड आमच्याकडे परत येतो, म्हणून वेबसाइट बटण, ईमेल लिंक आणि स्टॉल QR कोड वेगळे ओळखता — आणि मोजता — येतात.',
    ],
