  'Filter to Critical to see urgent items first.': [
    'पहले ज़रूरी आइटम देखने के लिए गंभीर से फ़िल्टर करें।',
    'आधी तातडीचे आयटम पाहण्यासाठी गंभीर नुसार फिल्टर करा.',
  ],
  "Filters, fan kits, oils: the parts each machine model wears out, and when. A daily check matches every machine on the installed base to these rules; a part shows here once it's within its lead time. Quote a customer's due parts in one go, or record that the part was changed to restart its clock.":
    [
      'फ़िल्टर, फ़ैन किट, ऑयल: हर मशीन मॉडल के घिसने वाले पार्ट, और कब। दैनिक जाँच इंस्टॉल्ड बेस की हर मशीन को इन नियमों से मिलाती है; पार्ट अपने लीड टाइम के भीतर आते ही यहाँ दिखता है। ग्राहक के देय पार्ट्स का एक बार में कोटेशन दें, या पार्ट बदलने का रिकॉर्ड डालकर उसकी घड़ी फिर शुरू करें।',
      'फिल्टर, फॅन किट, ऑइल: प्रत्येक मशीन मॉडेलचे झिजणारे पार्ट, आणि कधी. दैनिक तपासणी इन्स्टॉल्ड बेसवरील प्रत्येक मशीन या नियमांशी जुळवते; पार्ट त्याच्या लीड टाइममध्ये आल्यावर इथे दिसतो. ग्राहकाच्या देय पार्ट्सचे एकाच वेळी कोटेशन द्या, किंवा पार्ट बदलल्याची नोंद करून त्याचे घड्याळ पुन्हा सुरू करा.',
    ],
  'Filters{0}': ['फ़िल्टर{0}', 'फिल्टर{0}'],
