  Food: ['खाद्य', 'अन्न'],
  'Food & beverage': ['खाद्य और पेय', 'अन्न आणि पेये'],
  Footer: ['फ़ुटर', 'फूटर'],
  For: ['के लिए', 'साठी'],
  'For If… and Wait for a reply, connect both ways out, or leave one empty to end the journey there.':
    [
      'अगर… और जवाब की प्रतीक्षा के लिए, दोनों निकास जोड़ें, या एक ख़ाली छोड़कर वहीं यात्रा समाप्त करें।',
      'जर… आणि उत्तराची वाट पहा साठी, दोन्ही मार्ग जोडा, किंवा एक रिकामा ठेवून तिथेच प्रवास संपवा.',
    ],
  "For OEMs and their dealers. As the OEM: invite your dealers, give each a territory, and route enquiries to whoever covers the customer; you then see the dealer's stage, quotes and activity on every lead. As a dealer: enter the OEM's invite code, then accept or decline the leads it sends you.":
    [
      'OEM और उनके डीलरों के लिए। OEM के रूप में: अपने डीलरों को आमंत्रित करें, हर एक को क्षेत्र दें, और पूछताछ उस तक भेजें जो ग्राहक को कवर करता है; फिर आप हर लीड पर डीलर का चरण, कोटेशन और गतिविधि देखते हैं। डीलर के रूप में: OEM का आमंत्रण कोड डालें, फिर भेजी गई लीड स्वीकार या अस्वीकार करें।',
      'OEM आणि त्यांच्या डीलरसाठी. OEM म्हणून: तुमच्या डीलरना आमंत्रित करा, प्रत्येकाला प्रदेश द्या, आणि चौकशी ग्राहकाला सेवा देणाऱ्याकडे पाठवा; मग तुम्हाला प्रत्येक लीडवर डीलरचा टप्पा, कोटेशन आणि हालचाल दिसते. डीलर म्हणून: OEM चा आमंत्रण कोड टाका, मग पाठवलेल्या लीड स्वीकारा किंवा नाकारा.',
    ],
  'For OEMs and their dealers. The OEM invites dealers, gives each a territory and routes enquiries to them. A dealer accepts or declines the leads it is sent.':
    [
      'OEM और उनके डीलरों के लिए। OEM डीलरों को आमंत्रित करता है, हर एक को क्षेत्र देता है और पूछताछ उन्हें भेजता है। डीलर भेजी गई लीड स्वीकार या अस्वीकार करता है।',
      'OEM आणि त्यांच्या डीलरसाठी. OEM डीलरना आमंत्रित करतो, प्रत्येकाला प्रदेश देतो आणि चौकशी त्यांच्याकडे पाठवतो. डीलर पाठवलेल्या लीड स्वीकारतो किंवा नाकारतो.',
    ],
  'For OEMs with a dealer network and company sign-in.': [
    'डीलर नेटवर्क और कंपनी साइन-इन वाले OEM के लिए।',
    'डीलर नेटवर्क आणि कंपनी साइन-इन असलेल्या OEM साठी.',
  ],
  'For a closure, tick Out of office, choose the first and last closed day, and write the message.':
    [
      'बंदी के लिए, ऑफ़िस से बाहर पर निशान लगाएँ, पहला और आख़िरी बंद दिन चुनें, और संदेश लिखें।',
      'बंदसाठी, ऑफिसबाहेर वर खूण करा, पहिला आणि शेवटचा बंद दिवस निवडा, आणि संदेश लिहा.',
    ],
  'For a request received by email, phone or post. A request that comes through the opt-out keyword is logged automatically.':
    [
      'ईमेल, फ़ोन या डाक से मिले अनुरोध के लिए। ऑप्ट-आउट कीवर्ड से आया अनुरोध अपने आप दर्ज होता है।',
      'ईमेल, फोन किंवा टपालाने आलेल्या विनंतीसाठी. ऑप्ट-आउट कीवर्डने आलेली विनंती आपोआप नोंदवली जाते.',
    ],
  'For a workspace managing other client workspaces. A client issues an invite code; redeeming it gives read-only access you can enter and exit per client.':
    [
      'दूसरे क्लाइंट वर्कस्पेस संभालने वाले वर्कस्पेस के लिए। क्लाइंट आमंत्रण कोड जारी करता है; उसे रिडीम करने से केवल-पढ़ने वाला एक्सेस मिलता है जिसमें आप हर क्लाइंट के लिए आ-जा सकते हैं।',
      'इतर क्लायंट वर्कस्पेस सांभाळणाऱ्या वर्कस्पेससाठी. क्लायंट आमंत्रण कोड देतो; तो रिडीम केल्याने फक्त-वाचन प्रवेश मिळतो ज्यात प्रत्येक क्लायंटसाठी आत-बाहेर जाता येते.',
    ],
  'For courier rates by PIN code and weight, and shipments that track themselves. Create an API user in Shiprocket (Settings → API) and enter it here. Transporters you book directly work without it.':
    [
      'PIN कोड और वज़न के अनुसार कूरियर दरों के लिए, और अपने आप ट्रैक होने वाले शिपमेंट के लिए। Shiprocket में API यूज़र बनाएँ (Settings → API) और यहाँ डालें। आप जिन ट्रांसपोर्टरों को सीधे बुक करते हैं वे इसके बिना काम करते हैं।',
      'PIN कोड आणि वजनानुसार कुरिअर दरांसाठी, आणि आपोआप ट्रॅक होणाऱ्या शिपमेंटसाठी. Shiprocket मध्ये API युजर तयार करा (Settings → API) आणि इथे टाका. तुम्ही थेट बुक करता ते ट्रान्सपोर्टर याशिवाय चालतात.',
    ],
