      'ग्राहकाने मागील 24 तासांत संदेश पाठवला असल्यास, PDF स्वतः जाते. नाहीतर WhatsApp फक्त मंजूर टेम्पलेट स्वीकारते. काहीही पाठवता न आल्यास तुम्हाला कळवले जाईल.',
