  'If this lasts more than a few minutes, the platform may be down. Messages sent to your WhatsApp number are held by Meta and delivered when we are back.':
    [
      'अगर यह कुछ मिनटों से ज़्यादा चले, तो प्लेटफ़ॉर्म बंद हो सकता है। आपके WhatsApp नंबर पर भेजे संदेश Meta रखता है और हमारे लौटने पर पहुँचाता है।',
      'हे काही मिनिटांपेक्षा जास्त चालल्यास, प्लॅटफॉर्म बंद असू शकतो. तुमच्या WhatsApp नंबरवर पाठवलेले संदेश Meta ठेवते आणि आम्ही परत आल्यावर पोहोचवते.',
    ],
  'If this number already has a WhatsApp PIN, use it. Otherwise, choose six digits and keep them safe. This is not the verification code sent by SMS.':
    [
      'अगर इस नंबर का पहले से WhatsApp PIN है, तो उसे इस्तेमाल करें। वरना छह अंक चुनें और सुरक्षित रखें। यह SMS से भेजा सत्यापन कोड नहीं है।',
      'या नंबरचा आधीच WhatsApp PIN असल्यास, तो वापरा. नाहीतर सहा अंक निवडा आणि सुरक्षित ठेवा. हा SMS ने पाठवलेला पडताळणी कोड नाही.',
    ],
  "If you are a contact a tenant has messaged, or a member of a tenant's team, you can ask the tenant (as the party responsible for your data — see §7) to:":
    [
      'अगर आप वह संपर्क हैं जिसे किसी वर्कस्पेस ने संदेश भेजा, या किसी वर्कस्पेस टीम के सदस्य हैं, तो आप वर्कस्पेस से (आपके डेटा के ज़िम्मेदार पक्ष के रूप में — §7 देखें) कह सकते हैं:',
      'तुम्ही एखाद्या वर्कस्पेसने संदेश पाठवलेला संपर्क असाल, किंवा वर्कस्पेस टीमचे सदस्य असाल, तर तुम्ही वर्कस्पेसला (तुमच्या डेटासाठी जबाबदार पक्ष म्हणून — §7 पहा) सांगू शकता:',
    ],
  'If you hold no data about this person, reject the request and tell them so.': [
    'अगर आपके पास इस व्यक्ति का कोई डेटा नहीं है, तो अनुरोध अस्वीकार करें और उन्हें बताएँ।',
    'तुमच्याकडे या व्यक्तीचा कोणताही डेटा नसल्यास, विनंती नाकारा आणि त्यांना कळवा.',
  ],
  'If you received a message through MNI Assist, the business that messaged you (the "tenant") is who asked for your consent and is responsible for deciding what to send you — they are the data fiduciary under India\'s Digital Personal Data Protection Act, 2023. MNI Assist (Emnisoft Pvt Ltd) processes that data on the tenant\'s instructions, as its data processor / significant processing platform.':
    [
      'अगर आपको MNI Assist से संदेश मिला, तो आपको संदेश भेजने वाला बिज़नेस ("वर्कस्पेस") ही आपकी सहमति माँगने वाला है और आपको क्या भेजना है यह तय करने के लिए ज़िम्मेदार है — भारत के डिजिटल व्यक्तिगत डेटा संरक्षण अधिनियम, 2023 के तहत वह डेटा फ़िड्युशियरी है। MNI Assist (Emnisoft Pvt Ltd) उस डेटा को वर्कस्पेस के निर्देशों पर, उसके डेटा प्रोसेसर / महत्वपूर्ण प्रोसेसिंग प्लेटफ़ॉर्म के रूप में प्रोसेस करता है।',
      'तुम्हाला MNI Assist मार्फत संदेश मिळाला असल्यास, तुम्हाला संदेश पाठवणारा व्यवसाय ("वर्कस्पेस") तुमची संमती मागणारा आहे आणि तुम्हाला काय पाठवायचे ते ठरवण्यास जबाबदार आहे — भारताच्या डिजिटल वैयक्तिक डेटा संरक्षण कायदा, 2023 अंतर्गत तो डेटा फिड्युशियरी आहे. MNI Assist (Emnisoft Pvt Ltd) तो डेटा वर्कस्पेसच्या सूचनांनुसार, त्याचा डेटा प्रोसेसर / महत्त्वाचा प्रक्रिया प्लॅटफॉर्म म्हणून प्रक्रिया करते.',
    ],
