  "Large exports are built in the background so you don't have to wait on the page. You're notified (in the app and by email) when one is ready; download it here or from the email link within seven days.":
    [
      'बड़े एक्सपोर्ट बैकग्राउंड में बनते हैं ताकि आपको पेज पर इंतज़ार न करना पड़े। तैयार होने पर आपको सूचना मिलती है (ऐप में और ईमेल से); इसे सात दिनों के भीतर यहाँ से या ईमेल लिंक से डाउनलोड करें।',
      'मोठे एक्सपोर्ट पार्श्वभूमीत तयार होतात म्हणजे तुम्हाला पेजवर थांबावे लागत नाही. तयार झाल्यावर तुम्हाला सूचना मिळते (अॅपमध्ये आणि ईमेलने); सात दिवसांत इथून किंवा ईमेल लिंकवरून डाउनलोड करा.',
    ],
