  'MNI Assist — two-step verification recovery codes': [
    'MNI Assist — दो-चरण सत्यापन रिकवरी कोड',
    'MNI Assist — द्वि-टप्पी पडताळणी पुनर्प्राप्ती कोड',
  ],
  "MNI Assist's AI reads the conversation and your own knowledge base, then suggests the next reply. Nothing reaches a customer without a person, unless you switch on the assistant for questions it can answer with confidence.":
    [
      'MNI Assist का AI बातचीत और आपका अपना नॉलेज बेस पढ़ता है, फिर अगला जवाब सुझाता है। किसी व्यक्ति के बिना कुछ भी ग्राहक तक नहीं पहुँचता, जब तक आप उन सवालों के लिए सहायक चालू न करें जिनका वह भरोसे से जवाब दे सकता है।',
      'MNI Assist चे AI संभाषण आणि तुमचा स्वतःचा नॉलेज बेस वाचते, मग पुढचे उत्तर सुचवते. व्यक्तीशिवाय काहीही ग्राहकापर्यंत पोहोचत नाही, जोपर्यंत तुम्ही ते आत्मविश्वासाने उत्तर देऊ शकेल अशा प्रश्नांसाठी सहाय्यक चालू करत नाही.',
    ],
