  'No activity': ['कोई गतिविधि नहीं', 'हालचाल नाही'],
  'No ad account connected. Connect the Meta ad account your ads run from to see what each ad cost beside the chats and enquiries it brought. MNI Assist only reads spend; it cannot change your ads or budgets.':
    [
      'कोई विज्ञापन खाता नहीं जुड़ा। हर विज्ञापन की लागत उसकी लाई चैट और पूछताछ के साथ देखने के लिए वह Meta विज्ञापन खाता जोड़ें जिससे आपके विज्ञापन चलते हैं। MNI Assist केवल ख़र्च पढ़ता है; यह आपके विज्ञापन या बजट नहीं बदल सकता।',
      'कोणतेही जाहिरात खाते जोडलेले नाही. प्रत्येक जाहिरातीचा खर्च तिने आणलेल्या चॅट आणि चौकशीसोबत पाहण्यासाठी तुमच्या जाहिराती चालतात ते Meta जाहिरात खाते जोडा. MNI Assist फक्त खर्च वाचते; ते तुमच्या जाहिराती किंवा बजेट बदलू शकत नाही.',
    ],
  'No ad activity in this period. Chats opened from a Click-to-WhatsApp ad, leads from a lead form, and spend from a connected ad account appear here by ad.':
    [
      'इस अवधि में कोई विज्ञापन गतिविधि नहीं। Click-to-WhatsApp विज्ञापन से खुली चैट, लीड फ़ॉर्म से लीड, और जुड़े विज्ञापन खाते का ख़र्च यहाँ विज्ञापन के अनुसार दिखते हैं।',
      'या कालावधीत जाहिरात हालचाल नाही. Click-to-WhatsApp जाहिरातीतून उघडलेल्या चॅट, लीड फॉर्ममधून लीड, आणि जोडलेल्या जाहिरात खात्याचा खर्च इथे जाहिरातीनुसार दिसतो.',
    ],
