  'Onboarding {0} — next:': ['{0} ऑनबोर्डिंग — आगे:', '{0} ऑनबोर्डिंग — पुढे:'],
  'Once a day, each customer with parts coming due gets one message listing them, from your approved template. Body values in order: customer name, the parts due, the earliest due date. The first quick-reply button (e.g. “Send quotation”) drafts the quote for all their due parts; the second (e.g. “Call me”) alerts the team. A URL button ending in':
    [
      'दिन में एक बार, जिस ग्राहक के पार्ट देय होने वाले हैं उसे आपके स्वीकृत टेम्पलेट से उनकी सूची वाला एक संदेश मिलता है। बॉडी मान क्रम में: ग्राहक का नाम, देय पार्ट, सबसे पहली देय तिथि। पहला क्विक-रिप्लाई बटन (जैसे “कोटेशन भेजें”) उनके सभी देय पार्ट्स का कोटेशन बनाता है; दूसरा (जैसे “मुझे कॉल करें”) टीम को सूचित करता है। वेरिएबल पर ख़त्म होने वाला URL बटन',
      'दिवसातून एकदा, ज्या ग्राहकाचे पार्ट देय होत आहेत त्याला तुमच्या मंजूर टेम्पलेटमधून त्यांची यादी असलेला एक संदेश मिळतो. बॉडी मूल्ये क्रमाने: ग्राहकाचे नाव, देय पार्ट, सर्वात आधीची देय तारीख. पहिले क्विक-रिप्लाय बटण (उदा. “कोटेशन पाठवा”) त्यांच्या सर्व देय पार्ट्सचे कोटेशन तयार करते; दुसरे (उदा. “मला कॉल करा”) टीमला कळवते. व्हेरिएबलवर संपणारे URL बटण',
    ],
  'One inbox for every channel': ['हर चैनल के लिए एक इनबॉक्स', 'प्रत्येक चॅनेलसाठी एक इनबॉक्स'],
