  Orders: ['ऑर्डर', 'ऑर्डर'],
  'Orders directly': ['सीधे ऑर्डर करता है', 'थेट ऑर्डर करतो'],
  "Orders outside these terms still reach you, flagged with why. The customer only hears that you'll be in touch. Orders paid up front aren't affected.":
    [
      'इन शर्तों के बाहर के ऑर्डर भी आप तक पहुँचते हैं, कारण के साथ चिह्नित। ग्राहक को केवल यह बताया जाता है कि आप संपर्क करेंगे। पहले भुगतान वाले ऑर्डर प्रभावित नहीं होते।',
      'या अटींबाहेरील ऑर्डरही तुमच्यापर्यंत पोहोचतात, कारणासह चिन्हांकित. ग्राहकाला फक्त तुम्ही संपर्क साधाल एवढेच सांगितले जाते. आधी पैसे भरलेल्या ऑर्डरवर परिणाम होत नाही.',
    ],
  "Orders to suppliers, received into stock at their cost. Stock is valued at moving average cost, the method Tally's Average Cost and SAP Business One's Moving Average use. Sent orders count as on order on the Stock page.":
    [
      'सप्लायरों को ऑर्डर, उनकी लागत पर स्टॉक में प्राप्त। स्टॉक का मूल्य चलती औसत लागत पर होता है, वही तरीका जो Tally का Average Cost और SAP Business One का Moving Average इस्तेमाल करता है। भेजे गए ऑर्डर स्टॉक पेज पर ऑर्डर पर गिने जाते हैं।',
      'पुरवठादारांना ऑर्डर, त्यांच्या खर्चाने स्टॉकमध्ये स्वीकारल्या. स्टॉकचे मूल्य चल सरासरी खर्चाने होते, Tally चे Average Cost आणि SAP Business One चे Moving Average वापरतात तीच पद्धत. पाठवलेल्या ऑर्डर स्टॉक पेजवर ऑर्डरवर म्हणून मोजल्या जातात.',
    ],
  'Orders, invoices, service tickets and installed machines for one customer, on one screen.': [
    'एक ग्राहक के ऑर्डर, इनवॉइस, सर्विस टिकट और इंस्टॉल मशीनें, एक स्क्रीन पर।',
    'एका ग्राहकाच्या ऑर्डर, इनव्हॉइस, सर्व्हिस तिकिटे आणि इन्स्टॉल केलेली मशीन, एका स्क्रीनवर.',
  ],
