  'Point your Exotel number at this flow for': [
    'अपने Exotel नंबर को इस फ़्लो पर इंगित करें, इसके लिए',
    'तुमचा Exotel नंबर या फ्लोकडे निर्देशित करा, यासाठी',
  ],
  "Point your identity provider's issuer at MNI Assist and map the email domains it owns. People signing in from those domains are provisioned automatically with the role below.":
    [
      'अपने पहचान प्रदाता का issuer MNI Assist पर इंगित करें और उसके स्वामित्व वाले ईमेल डोमेन मैप करें। उन डोमेन से साइन इन करने वालों को नीचे की भूमिका के साथ अपने आप बनाया जाता है।',
      'तुमच्या ओळख प्रदात्याचा issuer MNI Assist कडे निर्देशित करा आणि त्याच्या मालकीचे ईमेल डोमेन मॅप करा. त्या डोमेनवरून साइन इन करणाऱ्यांना खालील भूमिकेसह आपोआप तयार केले जाते.',
    ],
  'Points from 0 to 100. Penalties are taken away, rewards added; “at most” caps how much one kind of signal can move a score. Saving rescores every customer.':
    [
      '0 से 100 तक अंक। दंड घटाए जाते हैं, पुरस्कार जोड़े जाते हैं; “अधिकतम” सीमित करता है कि एक तरह का संकेत स्कोर को कितना हिला सकता है। सहेजने से हर ग्राहक का फिर स्कोर होता है।',
      '0 ते 100 गुण. दंड वजा होतात, बक्षिसे जोडली जातात; “जास्तीत जास्त” एका प्रकारचा संकेत गुण किती हलवू शकतो ते मर्यादित करते. जतन केल्याने प्रत्येक ग्राहकाचे पुन्हा गुण ठरतात.',
    ],
