  'Quantities of each catalogue part at each location. Every change is a movement (received, issued, adjusted, counted), so the history explains every figure. Parts on an open re-order request are held (reserved) until the quotation is won or lost; a won quotation issues its parts.':
    [
      'हर स्थान पर हर कैटलॉग पार्ट की मात्रा। हर बदलाव एक मूवमेंट है (प्राप्त, जारी, समायोजित, गिना), इसलिए इतिहास हर आँकड़े को समझाता है। खुले री-ऑर्डर अनुरोध वाले पार्ट कोटेशन जीतने या हारने तक रोके (आरक्षित) जाते हैं; जीता कोटेशन अपने पार्ट जारी करता है।',
      'प्रत्येक ठिकाणी प्रत्येक कॅटलॉग पार्टचे प्रमाण. प्रत्येक बदल एक हालचाल आहे (मिळाले, जारी, समायोजित, मोजले), म्हणून इतिहास प्रत्येक आकडा स्पष्ट करतो. उघड्या री-ऑर्डर विनंतीतील पार्ट कोटेशन जिंकेपर्यंत किंवा गमावेपर्यंत राखून (आरक्षित) ठेवले जातात; जिंकलेले कोटेशन त्याचे पार्ट जारी करते.',
    ],
