  'Sales Orders capture confirmed customer PO numbers, delivery terms, and line items. From here you can issue GST Delivery Challans or Commercial Invoices directly.':
    [
      'सेल्स ऑर्डर पक्के ग्राहक PO नंबर, डिलीवरी शर्तें और लाइन आइटम दर्ज करते हैं। यहाँ से आप सीधे GST डिलीवरी चालान या वाणिज्यिक इनवॉइस जारी कर सकते हैं।',
      'सेल्स ऑर्डर निश्चित ग्राहक PO नंबर, डिलिव्हरी अटी आणि लाइन आयटम नोंदवतात. इथून तुम्ही थेट GST डिलिव्हरी चलने किंवा व्यावसायिक इनव्हॉइस जारी करू शकता.',
    ],
