      'या वर्कस्पेसमधील कोणासाठीही नवीन पासवर्ड सेट करा — उदा. लॉक झालेल्या मालकासाठी. त्यांचा सध्याचा पासवर्ड लागत नाही. ते सर्वत्र साइन आउट होतात, आणि तुम्ही ती खूण काढत नाही तोपर्यंत पुढच्या साइन-इनला स्वतःचा निवडायला सांगितले जाते.',
