  'The import could not be applied.': ['आयात लागू नहीं हो सका।', 'आयात लागू होऊ शकले नाही.'],
  'The import failed.': ['आयात विफल।', 'आयात अयशस्वी.'],
  'The in-browser phone has no SIP address to dial through.': [
    'ब्राउज़र फ़ोन के पास डायल करने के लिए SIP पता नहीं है।',
    'ब्राउझर फोनकडे डायल करण्यासाठी SIP पत्ता नाही.',
  ],
  'The invitation to {0} stops working at once. You can invite them again later.': [
    '{0} का आमंत्रण तुरंत काम करना बंद कर देता है। आप बाद में उन्हें फिर आमंत्रित कर सकते हैं।',
    '{0} चे आमंत्रण लगेच चालणे थांबते. तुम्ही त्यांना नंतर पुन्हा आमंत्रित करू शकता.',
  ],
  'The invite is a one-time link that expires. Until it is accepted it shows in the outstanding list below, where it can be resent or revoked.':
    [
      'आमंत्रण एक बार का लिंक है जो समाप्त होता है। स्वीकार होने तक यह नीचे बकाया सूची में दिखता है, जहाँ इसे फिर भेजा या वापस लिया जा सकता है।',
      'आमंत्रण ही एकदाची लिंक आहे जी कालबाह्य होते. स्वीकारेपर्यंत ती खालील प्रलंबित यादीत दिसते, जिथे ती पुन्हा पाठवता किंवा मागे घेता येते.',
    ],
  'The invoice PDF could not be downloaded.': [
    'इनवॉइस PDF डाउनलोड नहीं हो सकी।',
    'इनव्हॉइस PDF डाउनलोड होऊ शकली नाही.',
  ],
  'The invoice could not be checked.': ['इनवॉइस जाँचा नहीं जा सका।', 'इनव्हॉइस तपासता आले नाही.'],
  'The invoice could not be generated.': ['इनवॉइस नहीं बन सका।', 'इनव्हॉइस तयार होऊ शकले नाही.'],
  'The invoice matches the meter: {0} paid messages, {1} ({2}, inside tolerance).': [
    'इनवॉइस मीटर से मेल खाता है: {0} भुगतान वाले संदेश, {1} ({2}, सहनशीलता के भीतर)।',
    'इनव्हॉइस मीटरशी जुळते: {0} शुल्काचे संदेश, {1} ({2}, सहनशीलतेच्या आत).',
  ],
  'The journey ends when this path runs out of steps.': [
    'यह रास्ता चरणों से ख़ाली होने पर यात्रा समाप्त होती है।',
    'हा मार्ग पायऱ्यांनी संपल्यावर प्रवास संपतो.',
  ],
  'The journey stops': ['यात्रा रुकती है', 'प्रवास थांबतो'],
  'The last 100 messages, as a read-only copy; photos and documents are named, not sent. Only switch this on if your consent wording tells customers their conversation may be shared with the dealer.':
    [
      'आख़िरी 100 संदेश, केवल-पढ़ने वाली कॉपी के रूप में; फ़ोटो और दस्तावेज़ नाम से दिखते हैं, भेजे नहीं जाते। इसे केवल तब चालू करें जब आपके सहमति के शब्द ग्राहकों को बताते हों कि उनकी बातचीत डीलर से साझा हो सकती है।',
      'शेवटचे 100 संदेश, फक्त-वाचन प्रत म्हणून; फोटो आणि दस्तऐवज नावाने दिसतात, पाठवले जात नाहीत. तुमच्या संमतीच्या शब्दांत ग्राहकांना त्यांचे संभाषण डीलरसोबत शेअर होऊ शकते असे सांगितले असल्यासच हे चालू करा.',
    ],
  'The last 90 days of spend are imported as soon as you connect.': [
    'जोड़ते ही पिछले 90 दिनों का ख़र्च आयात होता है।',
    'जोडताच मागील 90 दिवसांचा खर्च आयात होतो.',
  ],
  'The last 90 days of spend are imported straight away.': [
    'पिछले 90 दिनों का ख़र्च तुरंत आयात होता है।',
    'मागील 90 दिवसांचा खर्च लगेच आयात होतो.',
  ],
  'The last attempt did not go through.': ['आख़िरी प्रयास नहीं हुआ।', 'शेवटचा प्रयत्न झाला नाही.'],
  'The last day must be on or after the first.': [
    'आख़िरी दिन पहले दिन या उसके बाद होना चाहिए।',
    'शेवटचा दिवस पहिल्या दिवशी किंवा त्यानंतर असावा.',
  ],
  'The last day of the closure must be on or after the first.': [
    'बंदी का आख़िरी दिन पहले दिन या उसके बाद होना चाहिए।',
    'बंदचा शेवटचा दिवस पहिल्या दिवशी किंवा त्यानंतर असावा.',
  ],
  'The lead could not be accepted.': ['लीड स्वीकार नहीं हो सकी।', 'लीड स्वीकारता आली नाही.'],
  'The lead could not be handed back.': ['लीड वापस नहीं सौंपी जा सकी।', 'लीड परत सोपवता आली नाही.'],
  'The ledger accounts that every voucher and statement is built on.': [
    'लेजर खाते जिन पर हर वाउचर और स्टेटमेंट बनता है।',
    'प्रत्येक व्हाउचर आणि स्टेटमेंट ज्यावर तयार होते ती लेजर खाती.',
  ],
  'The limits the API enforces. Crossing one is blocked at the point of the action, not the invoice — upgrade the plan first.':
    [
      'API जो सीमाएँ लागू करता है। किसी को पार करना कार्रवाई के समय ही रुकता है, इनवॉइस पर नहीं — पहले प्लान अपग्रेड करें।',
      'API लागू करते त्या मर्यादा. एखादी ओलांडणे कृतीच्या वेळीच थांबवले जाते, इनव्हॉइसवर नाही — आधी प्लॅन अपग्रेड करा.',
    ],
