  'The link ran out on {0}.': ['लिंक {0} को समाप्त हो गया।', 'लिंक {0} रोजी संपली.'],
  'The link.': ['लिंक।', 'लिंक.'],
  'The location could not be added.': ['स्थान नहीं जोड़ा जा सका।', 'ठिकाण जोडता आले नाही.'],
