  'Tickets could not be loaded.': ['टिकट लोड नहीं हो सके।', 'तिकिटे लोड होऊ शकली नाहीत.'],
  "Ticking a box records the visitor's word, not proof that the number or address is theirs. Marketing messages to a number nobody has confirmed carry a risk.":
    [
      'बॉक्स पर निशान लगाना विज़िटर की बात दर्ज करता है, यह प्रमाण नहीं कि नंबर या पता उनका है। किसी ने पक्का न किए नंबर पर मार्केटिंग संदेशों में जोखिम है।',
      'बॉक्सवर खूण करणे अभ्यागताचे म्हणणे नोंदवते, नंबर किंवा पत्ता त्यांचाच आहे याचा पुरावा नाही. कोणी खात्री न केलेल्या नंबरवर मार्केटिंग संदेशांत धोका असतो.',
    ],
