  Track: ['ट्रैक करें', 'ट्रॅक करा'],
  'Track a part by batch (oils, filters with a shelf life) or by serial number (drives, controllers, anything under warranty). Every unit received then needs its number, issues take the soonest expiry or oldest first, and any number can be traced to the customer it went to. Change it only while none is in stock: count it to zero first.':
    [
      'पार्ट को बैच (शेल्फ़ लाइफ़ वाले ऑयल, फ़िल्टर) या सीरियल नंबर (ड्राइव, कंट्रोलर, वारंटी वाली कोई भी चीज़) से ट्रैक करें। फिर हर प्राप्त यूनिट का नंबर चाहिए, जारी करने में सबसे जल्दी समाप्ति या सबसे पुराना पहले जाता है, और कोई भी नंबर उस ग्राहक तक ट्रेस हो सकता है जिसे वह गया। इसे केवल तब बदलें जब स्टॉक में कोई न हो: पहले गिनकर शून्य करें।',
      'पार्ट बॅचने (शेल्फ लाइफ असलेली ऑइल, फिल्टर) किंवा सिरीयल नंबरने (ड्राइव्ह, कंट्रोलर, वॉरंटी असलेले काहीही) ट्रॅक करा. मग प्रत्येक मिळालेल्या युनिटचा नंबर लागतो, जारी करताना लवकर संपणारे किंवा सर्वात जुने आधी जाते, आणि कोणताही नंबर तो ज्या ग्राहकाकडे गेला त्याच्यापर्यंत ट्रेस करता येतो. स्टॉकमध्ये काहीही नसतानाच हे बदला: आधी मोजून शून्य करा.',
    ],
