  'Unpaid ERP invoices': ['बकाया ERP इनवॉइस', 'न भरलेली ERP इनव्हॉइस'],
  'Unpaid invoices from Tally or SAP. When switched on, the customer gets your approved reminder 3 days before the due date, then at 7 and 15 days overdue. Each stage goes once; reminders stop when the ERP shows the invoice paid.':
    [
      'Tally या SAP के बकाया इनवॉइस। चालू होने पर, ग्राहक को देय तिथि से 3 दिन पहले, फिर 7 और 15 दिन देर पर आपका स्वीकृत रिमाइंडर मिलता है। हर चरण एक बार जाता है; ERP इनवॉइस भुगतान दिखाते ही रिमाइंडर रुक जाते हैं।',
      'Tally किंवा SAP मधील न भरलेली इनव्हॉइस. चालू असताना, ग्राहकाला देय तारखेच्या 3 दिवस आधी, मग 7 आणि 15 दिवस उशिरा तुमचे मंजूर स्मरणपत्र मिळते. प्रत्येक टप्पा एकदाच जातो; ERP इनव्हॉइस भरल्याचे दाखवताच स्मरणपत्रे थांबतात.',
    ],
