      'आपकी टीम ग्राहक कॉल का जवाब दे सकती है और अनुमति देने वाले ग्राहकों को कॉल कर सकती है। चैनल में Meta Cloud API नंबर जोड़ें और Meta में उस नंबर के लिए कॉलिंग चालू करें। केवल जुड़ा मैसेजिंग नंबर कॉलिंग की उपलब्धता पक्की नहीं करता।',
