  '“Window closed” means the customer has not messaged in 24 hours. Only approved templates can be sent then.':
    [
      '“विंडो बंद” का मतलब है ग्राहक ने 24 घंटों में संदेश नहीं भेजा। तब केवल स्वीकृत टेम्पलेट भेजे जा सकते हैं।',
      '“विंडो बंद” म्हणजे ग्राहकाने 24 तासांत संदेश पाठवला नाही. तेव्हा फक्त मंजूर टेम्पलेट पाठवता येतात.',
    ],
  "“Your VMC-850 is under AMC, so the visit is covered. I've raised ticket TK-2481 and Ravi will be with you tomorrow at 10 am.”":
    [
      '“आपका VMC-850 AMC में है, इसलिए विज़िट शामिल है। मैंने टिकट TK-2481 बनाया है और रवि कल सुबह 10 बजे आपके पास होंगे।”',
      '“तुमचे VMC-850 AMC मध्ये आहे, म्हणून भेट समाविष्ट आहे. मी तिकीट TK-2481 तयार केले आहे आणि रवी उद्या सकाळी 10 वाजता तुमच्याकडे असतील.”',
    ],
